from collections import deque
from itertools import combinations

cls = {'Garza': 1, 'Yates': 3, 'Zimmer': 3, 'Flores': 1,
       'Lynch': 2, 'King': 2, 'Meyer': 2, 'Ortiz': 2}
init = {'Garza': 'R', 'Yates': 'R', 'Zimmer': 'R', 'Flores': 'S',
        'Lynch': 'S', 'King': 'T', 'Meyer': 'T', 'Ortiz': 'T'}
names = list(cls)
idx = {b: i for i, b in enumerate(names)}
start = tuple(init[b] for b in names)


def owned(state, c):
    return [names[i] for i in range(len(names)) if state[i] == c]


def apply(state, changes):
    new = list(state)
    for building, owner in changes.items():
        new[idx[building]] = owner
    return tuple(new)


def successors(state):
    out = set()
    for a in 'RST':
        for b in 'RST':
            if a == b:
                continue
            A = owned(state, a)
            B = owned(state, b)
            # Trade type 1: one building for one building of the same class
            for x in A:
                for y in B:
                    if cls[x] == cls[y]:
                        out.add(apply(state, {x: b, y: a}))
            # Trade types 2 and 3: a gives one building of class c,
            # b gives two buildings of class c+1
            for x in A:
                if cls[x] in (1, 2):
                    cands = [y for y in B if cls[y] == cls[x] + 1]
                    for y, z in combinations(cands, 2):
                        out.add(apply(state, {x: b, y: a, z: a}))
    return out


# Exhaustive reachability over all sequences of valid trades
seen = {start}
dq = deque([start])
while dq:
    s = dq.popleft()
    for t in successors(s):
        if t not in seen:
            seen.add(t)
            dq.append(t)

print("Reachable ownership states:", len(seen))

options = {
    'A': ('R', {'Lynch', 'Meyer', 'Ortiz'}),
    'B': ('S', {'Garza', 'Meyer'}),
    'C': ('S', {'King', 'Meyer', 'Ortiz'}),
    'D': ('T', {'Flores', 'Yates'}),
    'E': ('T', {'Garza', 'Lynch'}),
}

impossible = []
witness_A = None
for key, (company, want) in options.items():
    match = None
    for s in seen:
        if set(owned(s, company)) == want:
            match = s
            break
    if match is None:
        print(f"Option {key}: UNREACHABLE")
        impossible.append(key)
    else:
        print(f"Option {key}: REACHABLE")
        if key == 'A':
            witness_A = match

# Invariant check: each trade is value-neutral per company with
# weights class1=4, class2=2, class3=1 (initial company values are all 6)
for c in 'RST':
    vals = {s: sum({1: 4, 2: 2, 3: 1}[cls[b]] for b in owned(s, c)) for s in seen}
    print(f"Company {c} value set over reachable states: {sorted(set(vals.values()))}")

if witness_A is not None:
    print("Witness for A (owner per building):",
          {b: witness_A[idx[b]] for b in names})

print("Options that CANNOT be true:", impossible)
if impossible == ['D']:
    print("Claimed answer A: CHECK FAIL (A is reachable; the correct answer is D)")
elif impossible:
    print("Claimed answer A:", "CHECK PASS" if impossible == ['A'] else "CHECK FAIL")
else:
    print("Claimed answer A: CHECK UNKNOWN (no unreachable option found)")
